import { ActionDefinition } from '../../../Action'
import { TableNameColumn, DocumentIdColumn, TemplateValueColumn } from '../../../../db'

export const createRecord = ActionDefinition({
    $id: '2de05916c31332002841b63b12d3aee1',
    name: 'Create Record',
    description:
        'Creates a record on any ServiceNow table. You can dynamically add and configure fields for the record. Server-side validation rules are enforced (data policy, business rules, dictionary-defined mandatory fields), but UI policy does not apply.',
    inputs: {
        table_name: TableNameColumn({
            label: 'Table',
            mandatory: true,
        }),
        values: TemplateValueColumn({
            label: 'Fields',
            mandatory: true,
            maxLength: 16000000,
            dependent: 'table_name',
        }),
    },
    outputs: {
        table_name: TableNameColumn({
            label: 'Table',
        }),
        record: DocumentIdColumn({
            label: 'Record',
            maxLength: 40,
            dependent: 'table_name',
        }),
    },
})
